using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace BorderRepair.RepairProps
{
    // Entry of the playable Berth 04 scene: the clinic as it is played (RepairProps_Clinic, loaded single so it is the
    // active scene and every runtime keyed to it installs as usual), then a copy of the district moved so its B1 gate
    // meets the clinic door (Berth04_Playable_District, additive, generated by ExteriorDistrictPass.BuildPlayable),
    // then Berth04Join opens the door between them. Neither original scene is changed.
    //
    // In the editor the scenes load through EditorSceneManager, so they need not be in the build settings. A player
    // build would need both in the build list (not added here).
    public sealed class Berth04Playable : MonoBehaviour
    {
        public const string ClinicScene = "Assets/RepairProps/Scenes/RepairProps_Clinic.unity";
        /// <summary>The copy of the clinic with its stations moved into the B1 (ExteriorDistrictPass.BuildPlayable).</summary>
        public const string PlayableClinicScene = RepairBenchV2Runtime.PlayableClinicPath;
        public const string DistrictScene = "Assets/RepairProps/Scenes/Berth04_Playable_District.unity";

        /// <summary>The clinic's tutorial starts from an AfterSceneLoad hook that saw this entry scene instead of the
        /// clinic, so the entry starts it; tests turn it off.</summary>
        public static bool StartTutorial = true;

        public static Berth04Playable Current { get; private set; }
        public bool Ready { get; private set; }
        public Berth04Join Join { get; private set; }

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        static void ResetStatics() { Current = null; StartTutorial = true; }

        void Awake()
        {
            if (Current != null && Current != this) { Destroy(gameObject); return; }
            Current = this;
            DontDestroyOnLoad(gameObject);
            StartCoroutine(Load());
        }

        void OnDestroy()
        {
            if (Current == this) Current = null;
        }

        IEnumerator Load()
        {
            yield return LoadScene(PlayableClinicScene, LoadSceneMode.Single);
            var clinic = SceneManager.GetSceneByPath(PlayableClinicScene);
            if (StartTutorial && !UnityEngine.XR.XRSettings.isDeviceActive) ClinicTutorialRuntime.Begin();
            yield return LoadScene(DistrictScene, LoadSceneMode.Additive);
            var district = SceneManager.GetSceneByPath(DistrictScene);
            if (!clinic.isLoaded || !district.isLoaded)
            {
                Debug.LogError("[Berth04] could not load " + (clinic.isLoaded ? DistrictScene : PlayableClinicScene));
                yield break;
            }
            SceneManager.SetActiveScene(clinic);
            // Let the clinic's runtimes finish their Awake/Start (the bench, the cyber kit) before the join scans it.
            yield return null;
            var host = new GameObject("Berth04 join (runtime only)");
            SceneManager.MoveGameObjectToScene(host, clinic);
            Join = host.AddComponent<Berth04Join>();
            Join.Bind(clinic, district);
            Ready = true;
        }

        static AsyncOperation LoadScene(string path, LoadSceneMode mode)
        {
#if UNITY_EDITOR
            return UnityEditor.SceneManagement.EditorSceneManager.LoadSceneAsyncInPlayMode(path, new LoadSceneParameters(mode));
#else
            return SceneManager.LoadSceneAsync(path, mode);
#endif
        }
    }
}
